void uart_init(void) {
    // This ISR calls xQueueSendFromISR, so its priority
    // number must be >= the FreeRTOS syscall limit (5).
    NVIC_SetPriority(USART1_IRQn, 5);
    NVIC_EnableIRQ(USART1_IRQn);
    // Lost bytes: use DMA circular RX or the UART FIFO.
}

